/**
 * inline-templates.js — read templates/*.html and inject them as a string
 * constant inside worker.js, between the markers below.
 *
 *   /* ── BEGIN MASTER TEMPLATE (auto-generated by inline-templates.js) ── *\/
 *   const MASTER_TEMPLATE = "...";
 *   /* ── END MASTER TEMPLATE ── *\/
 *
 * Run `node inline-templates.js` whenever you change templates/master.html,
 * THEN run `npx wrangler deploy`. Or use `npm run deploy` which chains both.
 */
"use strict";
const fs = require("fs");
const path = require("path");

const HERE = __dirname;
const TEMPLATES_DIR = path.join(HERE, "templates");
const WORKER_PATH = path.join(HERE, "worker.js");

const BEGIN = "/* ── BEGIN MASTER TEMPLATE (auto-generated by inline-templates.js) ── */";
const END   = "/* ── END MASTER TEMPLATE ── */";

const master = fs.readFileSync(path.join(TEMPLATES_DIR, "master.html"), "utf8");
console.log(`master.html → ${Math.round(master.length / 1024)} KB`);

const block = `${BEGIN}\nconst MASTER_TEMPLATE = ${JSON.stringify(master)};\n${END}`;

let worker = fs.readFileSync(WORKER_PATH, "utf8");

if (worker.includes(BEGIN) && worker.includes(END)) {
  // Replace existing block
  const re = new RegExp(
    BEGIN.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") +
    "[\\s\\S]*?" +
    END.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")
  );
  worker = worker.replace(re, block);
  console.log("replaced existing MASTER_TEMPLATE block");
} else {
  // Insert at top of file (after first line)
  const lines = worker.split("\n");
  // Insert just after any leading "use strict" / banner comments
  let inj = 0;
  while (inj < lines.length && (lines[inj].startsWith("//") || lines[inj].trim() === "" || lines[inj].includes("use strict"))) inj++;
  lines.splice(inj, 0, block, "");
  worker = lines.join("\n");
  console.log(`injected new MASTER_TEMPLATE block at line ${inj + 1}`);
}

fs.writeFileSync(WORKER_PATH, worker, "utf8");
console.log("worker.js updated");
